import{_ as a,o as e,c as n,aj as i}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20241211180435243.DiLpdMcw.png",p="/assets/image-20241211180518909.o0xMuVIN.png",o="/assets/image-20241211231632255.tYjSNlKH.png",l="/assets/image-20241211232846027.BnVM4gr8.png",E="/assets/image-20241211233119666.DR_uCrL5.png",r="/assets/image-20241211233139036.DhLJkrxx.png",c="/assets/image-20241211233546478.d-o5DoCa.png",g="/assets/image-20241211233632785.D51QB-SU.png",d="/assets/image-20241211233750170.DS7e3gb-.png",m="/assets/image-20241211234341812.CyEYxz7K.png",h="/assets/image-20241211234620705.01SrBAcU.png",B="/assets/image-20241211234427504.DxYBj_zz.png",A="/assets/image-20241211234916982.BmOn4AGo.png",u="/assets/image-20241212000638058.CXGI5uMD.png",_="/assets/image-20241212000808737.HY0Big8r.png",v="/assets/image-20241212000332204.BXIEL2VU.png",k="/assets/image-20241212000847946.7wdldtxY.png",b="/assets/image-20241212001524176.C2xAIkLp.png",D="/assets/image-20241212001606695.DHf1afWb.png",F="/assets/image-20241212001830626.CR9-7njy.png",C="/assets/image-20241212002037085.kyzUacxE.png",S="/assets/image-20241212002125620.mszy3oaI.png",V=JSON.parse('{"title":"02-仓颉开发环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md","filePath":"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md","lastUpdated":1733937807000,"__rawMarkdown":"# 02-仓颉开发环境搭建\\n\\n本章节主要介绍如何搭建运行仓颉的开发环境。\\n\\n我们可以将运行仓颉语言的开发环境分成 3 个：\\n\\n1. 仓颉官网提供的在线运行，最低代价的方式来体验和运行仓颉程序。\\n2. 下载安装仓颉 SDK，利用 vscode 安装仓颉语法提示插件，开发仓颉程序\\n3. 在**DevEco Studio** 中安装仓颉插件，开发仓颉程序\\n\\n## 仓颉语言 在线体验\\n\\n打开[https://cangjie-lang.cn/](https://cangjie-lang.cn/)，点击**在线体验**即可\\n\\n![image-20241211180435243](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211180435243.png)\\n\\n---\\n\\n---\\n\\n![image-20241211180518909](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211180518909.png)\\n\\n## vscode 安装仓颉插件\\n\\n### 下载安装 vscode\\n\\n首先我们要下载 vscode 编辑工具，Visual Studio Code（简称“VS Code” [1]）是 Microsoft 在 2015 年 4 月 30 日 Build 开发者大会上正式宣布一个运行于 Mac OS X、Windows 和 Linux 之上的，针对于编写现代 Web 和云应用的跨平台源代码编辑器。\\n\\n[下载地址](https://code.visualstudio.com/)\\n\\n![image-20241211231632255](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211231632255.png)\\n\\n安装成功后，打开是这个样子的。\\n\\n![image-20241211232846027](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211232846027.png)\\n\\n### 下载安装仓颉插件\\n\\n[下载地址](https://cangjie-lang.cn/download)\\n\\n![image-20241211233119666](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233119666.png)\\n\\n建议下载稳定版本，这样少踩一些坑。\\n\\n![image-20241211233139036](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233139036.png)\\n\\n要下载的东西一共两个\\n\\n1. SDK\\n2. vscode 插件\\n\\n![image-20241211233546478](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233546478.png)\\n\\n### 安装仓颉 SDK\\n\\n下载完仓颉 SDK 后，直接双击安装即可\\n\\n![image-20241211233632785](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233632785.png)\\n\\n打开你的终端，输入 命令查看仓颉 SDK 是否安装成功\\n\\n```\\ncjc -v\\n```\\n\\n![image-20241211233750170](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211233750170.png)\\n\\n### 安装 vscode 仓颉插件\\n\\n该插件的功能用于让 vscode 识别仓颉语法，和运行仓颉程序。\\n\\n![image-20241211234341812](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234341812.png)\\n\\n解压它，得到以下程序。\\n\\n![image-20241211234620705](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234620705.png)\\n\\n---\\n\\nvscode 安装离线插件\\n\\n![image-20241211234427504](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234427504.png)\\n\\n安装成功\\n\\n![image-20241211234916982](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241211234916982.png)\\n\\n此时，需要在 vscode 配置仓颉的 SDK，否则后续无法直接运行仓颉程序。\\n\\n![image-20241212000638058](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000638058.png)\\n\\n---\\n\\n![image-20241212000808737](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000808737.png)\\n\\n至此，我们的 vscode 的开发环境都搭好了。\\n\\n## 在**DevEco Studio** 中安装仓颉插件，开发仓颉程序\\n\\n如果想要在在**DevEco Studio** 中安装仓颉插件，开发仓颉程序，那么需要先申请报名。[申请链接](https://developer.huawei.com/consumer/cn/activityDetail/cangjie-beta/)\\n\\n申请通过后，会给你邮箱发送邮件，此时，你根据邮件指引即可。因为此过程在保密范围内，所以就不演示具体的步骤了。\\n\\n安装成功后，会在**DevEco Studio** 中显示仓颉插件选项\\n\\n![image-20241212000332204](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000332204.png)\\n\\n## 我们第一个仓颉程序\\n\\n接下来，我们就使用 vscode 开发第一个仓颉程序吧！\\n\\n1. 新建一个仓颉文件，后缀名是 **cj**\\n\\n   ![image-20241212000847946](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212000847946.png)\\n\\n2. 输入基本代码\\n\\n   ```c\\n   main() {\\n       println(\\"Hello World\\")\\n   }\\n   ```\\n\\n3. 编译仓颉程序\\n\\n   打开终端，输入以下命令\\n\\n   > cjc 表示使用安装好的 sdk 的内置命令 用来编译仓颉程序\\n   >\\n   > .\\\\01-hello.cj 是要编译的文件\\n   >\\n   > -o hello.exe 表示编译后的内容，生成到 hello.exe\\n\\n   ```js\\n    cjc .\\\\01-hello.cj  -o hello.exe\\n   ```\\n\\n   ![image-20241212001524176](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001524176.png)\\n\\n4. 运行仓颉程序，此时在终端中输入命令，即可运行我们的仓颉程序\\n\\n   ```\\n    .\\\\hello.exe\\n   ```\\n\\n   ![image-20241212001606695](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001606695.png)\\n\\n5. 你也可以直接利用 vscode 内置的运行功能，一键编译和运行\\n\\n   ![image-20241212001830626](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212001830626.png)\\n\\n---\\n\\n​ 构建和调试单文件\\n\\n​ ![image-20241212002037085](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212002037085.png)\\n\\n---\\n\\n运行成功\\n\\n![image-20241212002125620](02-%E4%BB%93%E9%A2%89%E5%BC%80%E5%8F%91%E7%8E%AF%E5%A2%83%E6%90%AD%E5%BB%BA.assets/image-20241212002125620.png)\\n\\n## 总结\\n\\n以上就是我们搭建仓颉开发环境的 3 种方式。 下一章节开始介绍基本语法，敬请期待。\\n"}'),x={name:"仓颉入门到实战/02-仓颉开发环境搭建/02-仓颉开发环境搭建.md"};function f(j,s,y,q,K,w){return e(),n("div",null,[...s[0]||(s[0]=[i('<h1 id="_02-仓颉开发环境搭建" tabindex="-1">02-仓颉开发环境搭建 <a class="header-anchor" href="#_02-仓颉开发环境搭建" aria-label="Permalink to &quot;02-仓颉开发环境搭建&quot;">​</a></h1><p>本章节主要介绍如何搭建运行仓颉的开发环境。</p><p>我们可以将运行仓颉语言的开发环境分成 3 个：</p><ol><li>仓颉官网提供的在线运行，最低代价的方式来体验和运行仓颉程序。</li><li>下载安装仓颉 SDK，利用 vscode 安装仓颉语法提示插件，开发仓颉程序</li><li>在<strong>DevEco Studio</strong> 中安装仓颉插件，开发仓颉程序</li></ol><h2 id="仓颉语言-在线体验" tabindex="-1">仓颉语言 在线体验 <a class="header-anchor" href="#仓颉语言-在线体验" aria-label="Permalink to &quot;仓颉语言 在线体验&quot;">​</a></h2><p>打开<a href="https://cangjie-lang.cn/" target="_blank" rel="noreferrer">https://cangjie-lang.cn/</a>，点击<strong>在线体验</strong>即可</p><p><img src="'+t+'" alt="image-20241211180435243"></p><hr><hr><p><img src="'+p+'" alt="image-20241211180518909"></p><h2 id="vscode-安装仓颉插件" tabindex="-1">vscode 安装仓颉插件 <a class="header-anchor" href="#vscode-安装仓颉插件" aria-label="Permalink to &quot;vscode 安装仓颉插件&quot;">​</a></h2><h3 id="下载安装-vscode" tabindex="-1">下载安装 vscode <a class="header-anchor" href="#下载安装-vscode" aria-label="Permalink to &quot;下载安装 vscode&quot;">​</a></h3><p>首先我们要下载 vscode 编辑工具，Visual Studio Code（简称“VS Code” [1]）是 Microsoft 在 2015 年 4 月 30 日 Build 开发者大会上正式宣布一个运行于 Mac OS X、Windows 和 Linux 之上的，针对于编写现代 Web 和云应用的跨平台源代码编辑器。</p><p><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">下载地址</a></p><p><img src="'+o+'" alt="image-20241211231632255"></p><p>安装成功后，打开是这个样子的。</p><p><img src="'+l+'" alt="image-20241211232846027"></p><h3 id="下载安装仓颉插件" tabindex="-1">下载安装仓颉插件 <a class="header-anchor" href="#下载安装仓颉插件" aria-label="Permalink to &quot;下载安装仓颉插件&quot;">​</a></h3><p><a href="https://cangjie-lang.cn/download" target="_blank" rel="noreferrer">下载地址</a></p><p><img src="'+E+'" alt="image-20241211233119666"></p><p>建议下载稳定版本，这样少踩一些坑。</p><p><img src="'+r+'" alt="image-20241211233139036"></p><p>要下载的东西一共两个</p><ol><li>SDK</li><li>vscode 插件</li></ol><p><img src="'+c+'" alt="image-20241211233546478"></p><h3 id="安装仓颉-sdk" tabindex="-1">安装仓颉 SDK <a class="header-anchor" href="#安装仓颉-sdk" aria-label="Permalink to &quot;安装仓颉 SDK&quot;">​</a></h3><p>下载完仓颉 SDK 后，直接双击安装即可</p><p><img src="'+g+'" alt="image-20241211233632785"></p><p>打开你的终端，输入 命令查看仓颉 SDK 是否安装成功</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cjc -v</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+d+'" alt="image-20241211233750170"></p><h3 id="安装-vscode-仓颉插件" tabindex="-1">安装 vscode 仓颉插件 <a class="header-anchor" href="#安装-vscode-仓颉插件" aria-label="Permalink to &quot;安装 vscode 仓颉插件&quot;">​</a></h3><p>该插件的功能用于让 vscode 识别仓颉语法，和运行仓颉程序。</p><p><img src="'+m+'" alt="image-20241211234341812"></p><p>解压它，得到以下程序。</p><p><img src="'+h+'" alt="image-20241211234620705"></p><hr><p>vscode 安装离线插件</p><p><img src="'+B+'" alt="image-20241211234427504"></p><p>安装成功</p><p><img src="'+A+'" alt="image-20241211234916982"></p><p>此时，需要在 vscode 配置仓颉的 SDK，否则后续无法直接运行仓颉程序。</p><p><img src="'+u+'" alt="image-20241212000638058"></p><hr><p><img src="'+_+'" alt="image-20241212000808737"></p><p>至此，我们的 vscode 的开发环境都搭好了。</p><h2 id="在deveco-studio-中安装仓颉插件-开发仓颉程序" tabindex="-1">在<strong>DevEco Studio</strong> 中安装仓颉插件，开发仓颉程序 <a class="header-anchor" href="#在deveco-studio-中安装仓颉插件-开发仓颉程序" aria-label="Permalink to &quot;在**DevEco Studio** 中安装仓颉插件，开发仓颉程序&quot;">​</a></h2><p>如果想要在在<strong>DevEco Studio</strong> 中安装仓颉插件，开发仓颉程序，那么需要先申请报名。<a href="https://developer.huawei.com/consumer/cn/activityDetail/cangjie-beta/" target="_blank" rel="noreferrer">申请链接</a></p><p>申请通过后，会给你邮箱发送邮件，此时，你根据邮件指引即可。因为此过程在保密范围内，所以就不演示具体的步骤了。</p><p>安装成功后，会在<strong>DevEco Studio</strong> 中显示仓颉插件选项</p><p><img src="'+v+'" alt="image-20241212000332204"></p><h2 id="我们第一个仓颉程序" tabindex="-1">我们第一个仓颉程序 <a class="header-anchor" href="#我们第一个仓颉程序" aria-label="Permalink to &quot;我们第一个仓颉程序&quot;">​</a></h2><p>接下来，我们就使用 vscode 开发第一个仓颉程序吧！</p><ol><li><p>新建一个仓颉文件，后缀名是 <strong>cj</strong></p><p><img src="'+k+`" alt="image-20241212000847946"></p></li><li><p>输入基本代码</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    println</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello World&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><p>编译仓颉程序</p><p>打开终端，输入以下命令</p><blockquote><p>cjc 表示使用安装好的 sdk 的内置命令 用来编译仓颉程序</p><p>.\\01-hello.cj 是要编译的文件</p><p>-o hello.exe 表示编译后的内容，生成到 hello.exe</p></blockquote><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cjc .\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">01</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">hello.cj  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o hello.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="`+b+'" alt="image-20241212001524176"></p></li><li><p>运行仓颉程序，此时在终端中输入命令，即可运行我们的仓颉程序</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> .\\hello.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+D+'" alt="image-20241212001606695"></p></li><li><p>你也可以直接利用 vscode 内置的运行功能，一键编译和运行</p><p><img src="'+F+'" alt="image-20241212001830626"></p></li></ol><hr><p>​ 构建和调试单文件</p><p>​ <img src="'+C+'" alt="image-20241212002037085"></p><hr><p>运行成功</p><p><img src="'+S+'" alt="image-20241212002125620"></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>以上就是我们搭建仓颉开发环境的 3 种方式。 下一章节开始介绍基本语法，敬请期待。</p>',62)])])}const M=a(x,[["render",f]]);export{V as __pageData,M as default};
